-- A store at schema 24 as main at 4df394a leaves it, the build this one replaces: schema-23.sql (the f563365 store)
-- migrated to 24 by the 4df394a MessageStore's own `upgradeSchema`, then dumped with `sqlite3 .dump`. Same synthetic
-- data as schema-23.sql (ellie@example.org: three encrypted messages with bob@example.org, read through old-1, one in
-- the group team@rooms.example.org and an archive checkpoint); the v24 step only added the rejection columns of
-- outbox and outgoing_updates. Generated by a scratch package on a git archive of 4df394a's Packages/MessageStore;
-- no real data.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE chats (
    account_id TEXT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL,
    pinned INTEGER NOT NULL DEFAULT 0, avatar_hash TEXT, notification_level TEXT NOT NULL DEFAULT 'all' CHECK(notification_level IN ('all','mentions')), muted_until REAL, room_nickname TEXT, PRIMARY KEY(account_id, id)
);
INSERT INTO chats VALUES('ellie@example.org','bob@example.org','Bob',0,NULL,'all',NULL,NULL);
INSERT INTO chats VALUES('ellie@example.org','team@rooms.example.org','Team',0,NULL,'all',NULL,'Ellie');
CREATE TABLE messages (
    account_id TEXT NOT NULL, id TEXT NOT NULL, chat_id TEXT NOT NULL,
    sender_id TEXT NOT NULL, body TEXT NOT NULL, sent_at REAL NOT NULL,
    outgoing INTEGER NOT NULL, starred INTEGER NOT NULL DEFAULT 0, reply_json TEXT, encryption_profile TEXT, wire_id TEXT, wire_id_authenticated INTEGER NOT NULL DEFAULT 0, unreadable_reason TEXT, stanza_id TEXT,
    PRIMARY KEY(account_id, id),
    FOREIGN KEY(account_id, chat_id) REFERENCES chats(account_id, id)
);
INSERT INTO messages VALUES('ellie@example.org','old-0','bob@example.org','bob@example.org','before 0',1790000000.0,0,0,NULL,'legacy',NULL,0,NULL,NULL);
INSERT INTO messages VALUES('ellie@example.org','old-1','bob@example.org','ellie@example.org','before 1',1790000001.0,1,0,NULL,'legacy',NULL,0,NULL,NULL);
INSERT INTO messages VALUES('ellie@example.org','old-2','bob@example.org','bob@example.org','before 2',1790000002.0,0,0,NULL,'legacy',NULL,0,NULL,NULL);
INSERT INTO messages VALUES('ellie@example.org','group-0','team@rooms.example.org','carol@example.org','in the group',1790000003.0,0,0,NULL,'modern',NULL,0,NULL,NULL);
CREATE TABLE encryption_state (
    account_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, snapshot BLOB NOT NULL
, sealed_account TEXT);
CREATE TABLE encrypted_outbox (
    account_id TEXT NOT NULL, message_id TEXT NOT NULL, wire BLOB NOT NULL,
    PRIMARY KEY(account_id,message_id),
    FOREIGN KEY(account_id,message_id) REFERENCES messages(account_id,id)
);
CREATE TABLE encrypted_inbox (
    account_id TEXT NOT NULL, sender TEXT NOT NULL, digest TEXT NOT NULL, message_id TEXT,
    PRIMARY KEY(account_id,sender,digest)
);
CREATE TABLE pending_encrypted_inbox (
    account_id TEXT NOT NULL, sender TEXT NOT NULL, digest TEXT NOT NULL, wire BLOB NOT NULL, reason TEXT NOT NULL DEFAULT 'trustPending',
    PRIMARY KEY(account_id,sender,digest)
);
CREATE TABLE outbox (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    account_id TEXT NOT NULL, message_id TEXT NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('queued','submitting','unconfirmed','failed','serverAccepted')),
    attempt_id TEXT, rejection TEXT, returned INTEGER NOT NULL DEFAULT 0, UNIQUE(account_id,message_id),
    FOREIGN KEY(account_id,message_id) REFERENCES messages(account_id,id)
);
CREATE TABLE stream_management (
    account_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, snapshot BLOB NOT NULL
);
CREATE TABLE archive_checkpoints (
    account_id TEXT NOT NULL, archive_id TEXT NOT NULL, revision INTEGER NOT NULL, cursor TEXT NOT NULL, stamp REAL,
    PRIMARY KEY(account_id,archive_id)
);
INSERT INTO archive_checkpoints VALUES('ellie@example.org','ellie@example.org',1,'archive-cursor-1',1790000002.0);
CREATE TABLE outgoing_updates (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL, id TEXT NOT NULL,
    kind TEXT NOT NULL, chat_id TEXT NOT NULL, target_message_id TEXT, target_wire_id TEXT,
    reactions_json TEXT, created_at REAL NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('queued','submitting','unconfirmed','failed','serverAccepted')),
    attempt_id TEXT, wire BLOB, rejection TEXT, returned INTEGER NOT NULL DEFAULT 0, UNIQUE(account_id,id),
    FOREIGN KEY(account_id,target_message_id) REFERENCES messages(account_id,id)
);
CREATE TABLE message_events (
    account_id TEXT NOT NULL, actor_id TEXT NOT NULL, id TEXT NOT NULL,
    chat_id TEXT NOT NULL, target_wire_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK(kind IN ('reaction','retraction','correction','delivered','displayed')),
    payload_json TEXT NOT NULL, updated_at REAL NOT NULL,
    PRIMARY KEY(account_id,actor_id,id)
);
CREATE TABLE account_preferences (account_id TEXT PRIMARY KEY, previews INTEGER NOT NULL DEFAULT 1, delivery_receipts INTEGER NOT NULL DEFAULT 1, read_receipts INTEGER NOT NULL DEFAULT 1, last_seen INTEGER NOT NULL DEFAULT 1, reaction_alerts INTEGER NOT NULL DEFAULT 1);
CREATE TABLE notification_candidates (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL, message_id TEXT NOT NULL,
    UNIQUE(account_id,message_id),
    FOREIGN KEY(account_id,message_id) REFERENCES messages(account_id,id)
);
CREATE TABLE group_message_references (
    account_id TEXT NOT NULL, room TEXT NOT NULL, message_id TEXT NOT NULL, stanza_id TEXT NOT NULL,
    PRIMARY KEY(account_id,message_id), FOREIGN KEY(account_id,message_id) REFERENCES messages(account_id,id) ON DELETE CASCADE
);
CREATE TABLE group_ciphertext_messages (
    account_id TEXT NOT NULL, sender TEXT NOT NULL, digest TEXT NOT NULL, message_id TEXT NOT NULL,
    PRIMARY KEY(account_id,sender,digest), FOREIGN KEY(account_id,message_id) REFERENCES messages(account_id,id) ON DELETE CASCADE
);
CREATE TABLE archive_rejections (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL, archive_id TEXT NOT NULL,
    message_id TEXT NOT NULL, reason TEXT NOT NULL, UNIQUE(account_id,archive_id,message_id)
);
CREATE TABLE attachments (
    account_id TEXT NOT NULL, message_id TEXT NOT NULL, name TEXT NOT NULL, media_type TEXT NOT NULL,
    size INTEGER NOT NULL, width INTEGER, height INTEGER, hash TEXT NOT NULL, cipher_hash TEXT,
    secret BLOB NOT NULL, url TEXT, upload_state TEXT CHECK(upload_state IN ('pending','uploaded')), task_id INTEGER, sealed_account TEXT,
    PRIMARY KEY(account_id, message_id),
    FOREIGN KEY(account_id, message_id) REFERENCES messages(account_id, id)
);
CREATE TABLE archive_backfill (
    account_id TEXT NOT NULL, archive_id TEXT NOT NULL, revision INTEGER NOT NULL,
    oldest_id TEXT NOT NULL, complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN (0,1)),
    PRIMARY KEY(account_id, archive_id)
);
CREATE TABLE pending_notification_candidates (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL, sender TEXT NOT NULL, digest TEXT NOT NULL,
    chat_id TEXT NOT NULL, sent_at REAL NOT NULL, UNIQUE(account_id,sender,digest),
    FOREIGN KEY(account_id,sender,digest) REFERENCES pending_encrypted_inbox(account_id,sender,digest) ON DELETE CASCADE
);
CREATE TABLE chat_read_state (
    account_id TEXT NOT NULL, chat_id TEXT NOT NULL,
    read_sent_at REAL NOT NULL, read_message_id TEXT NOT NULL,
    publish_pending INTEGER NOT NULL DEFAULT 0 CHECK(publish_pending IN (0,1)),
    published_stanza_id TEXT,
    PRIMARY KEY(account_id, chat_id)
);
INSERT INTO chat_read_state VALUES('ellie@example.org','bob@example.org',1790000001.0,'old-1',1,NULL);
CREATE TABLE read_baselines (
    account_id TEXT NOT NULL, archive_id TEXT NOT NULL, sent_at REAL NOT NULL,
    PRIMARY KEY(account_id, archive_id)
);
CREATE TABLE reaction_notification_candidates (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL, chat_id TEXT NOT NULL,
    actor_id TEXT NOT NULL, target_message_id TEXT NOT NULL, reactions_json TEXT NOT NULL, reacted_at REAL NOT NULL,
    UNIQUE(account_id,chat_id,actor_id,target_message_id),
    FOREIGN KEY(account_id,target_message_id) REFERENCES messages(account_id,id) ON DELETE CASCADE
);
CREATE TABLE reaction_notifications_posted (
    account_id TEXT NOT NULL, chat_id TEXT NOT NULL, actor_id TEXT NOT NULL, target_message_id TEXT NOT NULL,
    reactions_json TEXT NOT NULL,
    PRIMARY KEY(account_id,chat_id,actor_id,target_message_id),
    FOREIGN KEY(account_id,target_message_id) REFERENCES messages(account_id,id) ON DELETE CASCADE
);
CREATE TABLE archive_gaps (
    account_id TEXT NOT NULL, archive_id TEXT NOT NULL, cursor TEXT NOT NULL, since REAL, detected_at REAL NOT NULL,
    PRIMARY KEY(account_id, archive_id, cursor)
);
CREATE INDEX timeline ON messages(account_id, chat_id, sent_at, id);
CREATE INDEX outbox_queue ON outbox(account_id,state,sequence);
CREATE INDEX authenticated_message_wire ON messages(account_id,chat_id,wire_id) WHERE wire_id_authenticated=1;
CREATE INDEX message_wire ON messages(account_id,chat_id,wire_id);
CREATE INDEX outgoing_update_queue ON outgoing_updates(account_id,state,sequence);
CREATE INDEX event_target ON message_events(account_id,chat_id,target_wire_id,kind,actor_id,updated_at,id);
CREATE INDEX group_reference_target ON group_message_references(account_id,room,stanza_id);
CREATE INDEX message_stanza ON messages(account_id,chat_id,stanza_id) WHERE stanza_id IS NOT NULL;
COMMIT;
PRAGMA user_version=24;
